$nodeScript = @'
const fs = require('fs')
const { PNG } = require('pngjs')
const images = [
  ['reference', 'D:/repository/苏住房G/worktrees/task2468-navbar-visual/e2e/home-v2/fixtures/navbar-reference.png'],
  ['actual', 'D:/repository/苏住房G/worktrees/task2468-navbar-visual/e2e/artifacts/task2468-navbar-visual/navbar-visual-1920.png']
]
for (const [name, path] of images) {
  const image = PNG.sync.read(fs.readFileSync(path))
  console.log(name)
  for (const y of [18, 19, 20, 21, 22, 89, 90, 91, 92]) {
    const runs = []
    let start = -1
    for (let x = 350; x < 700; x++) {
      const i = (y * image.width + x) * 4
      const bright = image.data[i] > 130 && image.data[i + 1] > 165 && image.data[i + 2] > 195
      if (bright && start < 0) start = x
      if (!bright && start >= 0) { if (x - start >= 10) runs.push(`${start}-${x - 1}`); start = -1 }
    }
    if (start >= 0 && 700 - start >= 10) runs.push(`${start}-699`)
    console.log(`y=${y}: ${runs.join(', ')}`)
  }
}
'@
node -e $nodeScript
